mapper.select:
SELECT COUNT(*)
FROM spu_basic_attr_values bav
INNER JOIN spu s ON bav.spu_id = s.id AND s.is_deleted = 0
WHERE s.category_id = #{categoryId}
  AND bav.attr_id = #{attrId}

SELECT COUNT(*)
FROM spu_sale_attr_choice sac
INNER JOIN spu s ON sac.spu_id = s.id AND s.is_deleted = 0
WHERE s.category_id = #{categoryId}
  AND sac.attr_id = #{attrId}
